cat > /app/irc.py <<'PY'
import asyncio,sqlite3,json,os
from server import init_db,con,emit
clients={}
async def send(w,s):w.write((s+'\r\n').encode());await w.drain()
async def client(r,w):
 nick='*'; user=None; token=None; joined=set()
 try:
  while (b:=await r.readline()):
   z=b.decode(errors='ignore').strip(); q=z.split(); cmd=q[0].upper() if q else ''
   if cmd=='PASS':token=q[1] if len(q)>1 else ''
   elif cmd=='NICK':
    n=q[1]; 
    if n.lower() in clients and clients[n.lower()] is not w: await send(w,f':huddle 433 * {n} :Nickname is already in use');continue
    nick=n
   elif cmd=='USER' and token:
    x=con.execute('SELECT u.* FROM users u JOIN tokens t ON t.user_id=u.id WHERE t.token=?',(token,)).fetchone()
    if not x: await send(w,':huddle 464 * :Password incorrect');return
    user=x;clients[nick.lower()]=w
    for n in ['001','002','003','004','005']:await send(w,f':huddle {n} {nick} :Welcome to Huddle')
    await send(w,f':huddle 422 {nick} :MOTD File is missing')
   elif cmd=='PING':await send(w,':huddle PONG huddle :'+(q[1] if len(q)>1 else ''))
   elif cmd=='QUIT':return
   elif not user:await send(w,f':huddle 421 {nick} {cmd} :Unknown command')
   elif cmd=='JOIN':
    name=q[1]; parts=name[1:].split('/') if name.startswith('#') else []
    c=con.execute('SELECT c.*,w.slug FROM channels c JOIN workspaces w ON w.id=c.workspace_id WHERE w.slug=? AND c.name=?',(parts[0],parts[1])).fetchone() if len(parts)==2 else None
    if not c:await send(w,f':huddle 403 {nick} {name} :No such channel');continue
    joined.add(c['id']);await send(w,f':{nick}!{user["username"]}@huddle JOIN {name}');await send(w,f':huddle 331 {nick} {name} :No topic is set')
   elif cmd=='PRIVMSG':
    name=q[1];text=z.split(' :',1)[1] if ' :' in z else '';parts=name[1:].split('/');c=con.execute('SELECT c.*,w.slug FROM channels c JOIN workspaces w ON w.id=c.workspace_id WHERE w.slug=? AND c.name=?',(parts[0],parts[1])).fetchone() if len(parts)==2 else None
    if c and c['id'] in joined:
     con.execute('INSERT INTO messages(channel_id,author_id,body,created_at) VALUES(?,?,?,datetime("now"))',(c['id'],user['id'],text));r0=con.execute('SELECT * FROM messages WHERE id=last_insert_rowid()').fetchone();emit(c['id'],'message.created',{'message':{'id':r0['id'],'channel_id':c['id'],'author_id':user['id'],'body':text}})
 finally:
  clients.pop(nick.lower(),None);w.close()
async def main():
 init_db();s=await asyncio.start_server(client,'0.0.0.0',6667);async with s:await s.serve_forever()
asyncio.run(main())
